/** `standard`: up is good. `inverted`: down is good (latency, error rate, churn). */
export type KpiSemantics = "inverted" | "neutral" | "standard";

export type KpiTone = "flat" | "negative" | "neutral" | "positive";

export type KpiMetricsInput = {
  previousValue?: number;
  semantics: KpiSemantics;
  targetValue?: number | null;
  value: number;
};

export type KpiMetrics = {
  delta: number;
  /** Change in percent of `previousValue`; `null` without one or when it is zero. */
  deltaPercent: number | null;
  hasComparison: boolean;
  showTarget: boolean;
  targetProgress: number;
  tone: KpiTone;
};

function resolveTone(delta: number, semantics: KpiSemantics): KpiTone {
  if (semantics === "neutral") return "neutral";
  if (delta === 0) return "flat";

  const isGood = semantics === "standard" ? delta > 0 : delta < 0;
  return isGood ? "positive" : "negative";
}

/** Comparison, tone and target progress, derived from the props. */
export function computeKpiMetrics({
  previousValue,
  semantics,
  targetValue = null,
  value,
}: KpiMetricsInput): KpiMetrics {
  const hasComparison = previousValue != null;
  const delta = hasComparison ? value - previousValue : 0;
  const deltaPercent =
    hasComparison && previousValue !== 0
      ? (delta / Math.abs(previousValue)) * 100
      : null;
  const tone = resolveTone(delta, semantics);
  const showTarget = targetValue != null && targetValue !== 0;
  const targetProgress = showTarget
    ? Math.min(100, Math.max(0, (value / targetValue) * 100))
    : 0;

  return {
    delta,
    deltaPercent,
    hasComparison,
    showTarget,
    targetProgress,
    tone,
  };
}

export const CHART_VERTICAL_PADDING = 4;

/** Lowest bar height, as a fraction: bars scale from the minimum, which would be zero. */
export const MIN_BAR_HEIGHT_RATIO = 0.18;

export type BarGeometry = {
  height: number;
  width: number;
  x: number;
  y: number;
};

type GeometryOptions = {
  height: number;
  padding?: number;
  width: number;
};

export function computeBarGeometry(
  data: number[],
  { height, padding = CHART_VERTICAL_PADDING, width }: GeometryOptions,
): BarGeometry[] {
  if (data.length === 0) return [];

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min;
  const drawableHeight = height - padding * 2;
  const baseline = height - padding;
  const barWidth = Math.max(2, width / data.length - 2);

  return data.map((point, index) => {
    // A flat series has no spread; draw it at full height.
    const ratio = range === 0 ? 1 : (point - min) / range;
    const scaled = Math.min(
      1,
      MIN_BAR_HEIGHT_RATIO + (1 - MIN_BAR_HEIGHT_RATIO) * ratio,
    );
    const barHeight = drawableHeight * scaled;

    return {
      height: barHeight,
      width: barWidth,
      x: (index / data.length) * width,
      y: baseline - barHeight,
    };
  });
}

"use client";

import {
  CHART_VERTICAL_PADDING,
  computeBarGeometry,
} from "./sparkline-geometry";

export type SparklineType = "bar" | "line";

const WIDTH = 120;
const HEIGHT = 40;

type SparklineProps = {
  data: number[];
  type?: SparklineType;
};

/** Decorative: the numbers beside it carry the information. */
export function Sparkline({ data, type = "line" }: SparklineProps) {
  if (data.length === 0) return null;

  if (type === "bar") {
    return (
      <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
        {computeBarGeometry(data, { height: HEIGHT, width: WIDTH }).map(
          (bar, index) => (
            <rect
              fill="currentColor"
              height={bar.height}
              key={index}
              opacity={0.6}
              style={{ "--kpi-bar-index": index } as React.CSSProperties}
              width={bar.width}
              x={bar.x}
              y={bar.y}
            />
          ),
        )}
      </svg>
    );
  }

  // A one-point polyline renders nothing; draw a dot.
  if (data.length === 1) {
    return (
      <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
        <circle cx={WIDTH / 2} cy={HEIGHT / 2} fill="currentColor" r={2.5} />
      </svg>
    );
  }

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const drawableHeight = HEIGHT - CHART_VERTICAL_PADDING * 2;

  const lastIndex = data.length - 1;
  const points = data
    .map((point, index) => {
      const x = (index / lastIndex) * WIDTH;
      const y =
        HEIGHT -
        CHART_VERTICAL_PADDING -
        ((point - min) / range) * drawableHeight;
      return `${x},${y}`;
    })
    .join(" ");

  return (
    <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
      {/* `pathLength={1}` renormalises the line to a single unit so the
          stylesheet can draw it with a dash of 1, whatever the data does to its
          real length. */}
      <polyline
        fill="none"
        pathLength={1}
        points={points}
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={2}
      />
    </svg>
  );
}

import type { KpiValuePart } from "./format-value";

type ValuePartsProps = {
  parts: KpiValuePart[];
};

/** One span per part, so digits, notation and unit can be styled apart. */
export function ValueParts({ parts }: ValuePartsProps) {
  return parts.map((part, index) => (
    <span
      className={`kpi-value-part kpi-value-part--${part.kind}`}
      // Parts repeat within a number, so position is the only key.
      key={`${index}-${part.kind}-${part.value}`}
    >
      {part.value}
    </span>
  ));
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentPropsWithRef,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

import {
  formatPercentChange,
  formatValueParts,
  partsToText,
  type KpiFormat,
} from "./internal/format-value";
import {
  ArrowDownRightIcon,
  ArrowUpRightIcon,
  CheckIcon,
  CopyIcon,
  ExternalLinkIcon,
  MinusIcon,
} from "./internal/icons";
import { computeKpiMetrics, type KpiSemantics } from "./internal/metrics";
import { Sparkline, type SparklineType } from "./internal/sparkline";
import { ValueParts } from "./internal/value-parts";

export type { KpiSemantics } from "./internal/metrics";

export type KpiChartType = SparklineType | "none";

export type KpiProps = {
  /** Replaces the default "open in new tab" glyph of the action button. */
  actionIcon?: ReactNode;
  /** Accessible name of the action button. */
  actionLabel?: string;
  chartType?: KpiChartType;
  className?: string;
  /** Caption next to the trend badge. */
  comparisonLabel?: string;
  /** Announced via a polite status region after a successful copy. */
  copiedLabel?: string;
  /** Accessible name of the copy button. */
  copyLabel?: string;
  /** ISO 4217 code, used when `format` is `"currency"`. */
  currency?: string;
  /** Panel shown on hover, keyboard focus or tap. No panel when omitted. */
  details?: ReactNode;
  /** Accessible name of the details group. */
  detailsLabel?: string;
  format?: KpiFormat;
  /** Fixed decimals for the value and target. Each format has its own default. */
  fractionDigits?: number;
  /** Oldest value first. */
  historyData?: number[];
  isLoading?: boolean;
  /** BCP 47 tag driving number, currency and percentage formatting. */
  locale?: string;
  onActionClick?: () => void;
  previousValue?: number;
  semantics?: KpiSemantics;
  showCopyButton?: boolean;
  targetLabel?: string;
  /** Renders the progress footer when set. */
  targetValue?: number | null;
  title: string;
  value: number;
  /** Unit after the value and target (`"km/s"`). Currency and percent come from `format`. */
  valueUnit?: string;
};

const COPIED_RESET_MS = 2000;
const DETAILS_OPEN_DELAY_MS = 500;
const DETAILS_CLOSE_DELAY_MS = 200;
const TOUCH_TAP_MOVE_TOLERANCE_PX = 8;

/** Stable default, so `memo` still works. */
const NO_HISTORY: number[] = [];

/**
 * KPI card: a title, one large value, an optional trend badge, sparkline,
 * target progress and a details panel.
 *
 * @example
 * <Kpi
 *   comparisonLabel="vs last month"
 *   format="currency"
 *   historyData={[38_100, 39_400, 41_200, 42_800]}
 *   previousValue={41_200}
 *   targetValue={50_000}
 *   title="Monthly recurring revenue"
 *   value={42_800}
 * />
 */
export function Kpi({
  actionIcon,
  actionLabel = "Open details",
  chartType = "line",
  className,
  comparisonLabel = "vs last period",
  copiedLabel = "Value copied",
  copyLabel = "Copy raw value",
  currency = "USD",
  details,
  detailsLabel = "Additional details",
  format = "number",
  fractionDigits,
  historyData = NO_HISTORY,
  isLoading = false,
  locale = "en-US",
  onActionClick,
  previousValue,
  semantics = "standard",
  showCopyButton = true,
  targetLabel = "Goal",
  targetValue = null,
  title,
  value,
  valueUnit,
}: KpiProps) {
  const [copied, setCopied] = useState(false);
  const progressLabelId = useId();
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const detailsActive = details != null;

  const clearCopyTimer = useCallback(() => {
    if (copyTimerRef.current != null) {
      clearTimeout(copyTimerRef.current);
      copyTimerRef.current = null;
    }
  }, []);

  useEffect(() => () => clearCopyTimer(), [clearCopyTimer]);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(String(value));
      clearCopyTimer();
      setCopied(true);
      copyTimerRef.current = setTimeout(() => {
        setCopied(false);
        copyTimerRef.current = null;
      }, COPIED_RESET_MS);
    } catch {
      // No clipboard access (insecure origin or denied permission).
    }
  }, [clearCopyTimer, value]);

  const rootClassName = ["kpi-theme", "kpi", className]
    .filter(Boolean)
    .join(" ");
  // With details the shell is the root, so layout classes belong on it.
  const cardClassName = detailsActive ? "kpi-theme kpi" : rootClassName;

  if (isLoading) {
    return (
      <div aria-busy="true" className={`${rootClassName} kpi--loading`}>
        <div className="kpi-skeleton kpi-skeleton--title" />
        <div className="kpi-skeleton kpi-skeleton--value" />
        <div className="kpi-skeleton kpi-skeleton--footer" />
      </div>
    );
  }

  const {
    delta,
    deltaPercent,
    hasComparison,
    showTarget,
    targetProgress,
    tone,
  } = computeKpiMetrics({ previousValue, semantics, targetValue, value });

  const TrendIcon =
    delta > 0 ? ArrowUpRightIcon : delta < 0 ? ArrowDownRightIcon : MinusIcon;
  const showChart = historyData.length > 0 && chartType !== "none";
  const visibleDeltaPercent = formatPercentChange(deltaPercent, { locale });
  const signedDeltaPercent =
    deltaPercent == null
      ? null
      : formatPercentChange(deltaPercent, { locale, signed: true });

  const formatOptions = {
    currency,
    format,
    fractionDigits,
    locale,
    unit: valueUnit,
  };
  const valueParts = formatValueParts(value, formatOptions);

  const card = (
    <div className={`${cardClassName} kpi--tone-${tone}`}>
      <div className="kpi-header">
        <h3 className="kpi-title">{title}</h3>

        <div className="kpi-actions">
          {showCopyButton ? (
            <KpiButton
              aria-label={copyLabel}
              className={copied ? "kpi-button--success" : undefined}
              onClick={handleCopy}
            >
              {copied ? <CheckIcon /> : <CopyIcon />}
            </KpiButton>
          ) : null}
          {onActionClick ? (
            <KpiButton aria-label={actionLabel} onClick={onActionClick}>
              {actionIcon ?? <ExternalLinkIcon />}
            </KpiButton>
          ) : null}
        </div>
      </div>

      <span aria-live="polite" className="kpi-sr-only" role="status">
        {copied ? copiedLabel : ""}
      </span>

      <div className="kpi-body">
        {/* Remounting on a new value replays the CSS fade in `.kpi-value-animate`. */}
        <span
          className="kpi-value kpi-value-animate"
          key={partsToText(valueParts)}
        >
          <ValueParts parts={valueParts} />
        </span>

        {hasComparison ? (
          <div className="kpi-trend">
            <span className="kpi-trend-badge">
              <TrendIcon size={10} />
              {signedDeltaPercent != null ? (
                <>
                  <span aria-hidden="true">{visibleDeltaPercent}</span>
                  <span className="kpi-sr-only">{signedDeltaPercent}</span>
                </>
              ) : (
                visibleDeltaPercent
              )}
            </span>
            <span className="kpi-trend-comparison">{comparisonLabel}</span>
          </div>
        ) : null}

        {showChart ? (
          <div className="kpi-chart">
            <Sparkline data={historyData} type={chartType} />
          </div>
        ) : null}
      </div>

      {showTarget ? (
        <div className="kpi-footer">
          <div className="kpi-footer-row">
            <span className="kpi-footer-label" id={progressLabelId}>
              {targetLabel}
            </span>
            <span className="kpi-footer-value">
              <ValueParts parts={valueParts} />
              <span className="kpi-value-part kpi-value-part--literal">
                {" "}
                /{" "}
              </span>
              <ValueParts
                parts={formatValueParts(targetValue, formatOptions)}
              />
            </span>
          </div>
          <div
            aria-labelledby={progressLabelId}
            aria-valuemax={100}
            aria-valuemin={0}
            aria-valuenow={Math.round(targetProgress)}
            className="kpi-progress"
            role="progressbar"
          >
            {/* The fill's width and its entrance both live in the stylesheet;
                this passes the fraction and nothing else. */}
            <div
              className="kpi-progress-fill"
              style={
                {
                  "--kpi-progress": targetProgress / 100,
                } as React.CSSProperties
              }
            />
          </div>
        </div>
      ) : null}
    </div>
  );

  if (!detailsActive) return card;

  return (
    <KpiDetailsShell
      className={className}
      details={details}
      detailsLabel={detailsLabel}
      // With no button inside, the shell itself must be focusable.
      focusLabel={showCopyButton || onActionClick ? undefined : title}
    >
      {card}
    </KpiDetailsShell>
  );
}

export type KpiDetailRow = {
  label: string;
  value: string;
};

type KpiDetailsProps = {
  rows: KpiDetailRow[];
};

/** Label/value list for the `details` prop. */
export function KpiDetails({ rows }: KpiDetailsProps) {
  if (rows.length === 0) return null;

  return (
    <dl className="kpi-details-list">
      {rows.map((row) => (
        <div className="kpi-details-row" key={row.label}>
          <dt className="kpi-details-label">{row.label}</dt>
          <dd className="kpi-details-value">{row.value}</dd>
        </div>
      ))}
    </dl>
  );
}

type KpiDetailsShellProps = {
  children: ReactNode;
  className?: string;
  details: ReactNode;
  detailsLabel: string;
  /** When set, the shell itself takes focus, named by this. */
  focusLabel?: string;
};

type TouchPress = {
  pointerId: number;
  startX: number;
  startY: number;
};

/** Whether focus came from a keyboard. Without `:focus-visible`, assume it did. */
function isKeyboardFocus(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return true;
  try {
    return target.matches(":focus-visible");
  } catch {
    return true;
  }
}

function isTouchToggleTarget(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;

  return (
    target.closest(
      ".kpi-details, a, button, input, select, textarea, [contenteditable], [role='button'], [role='link']",
    ) == null
  );
}

/** Open state and timers; lives only while `details` is set. */
function KpiDetailsShell({
  children,
  className,
  details,
  detailsLabel,
  focusLabel,
}: KpiDetailsShellProps) {
  const [open, setOpen] = useState(false);
  const detailsId = useId();
  const openTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const touchPressRef = useRef<TouchPress | null>(null);
  const shellRef = useRef<HTMLDivElement>(null);
  /** A tap-opened panel ignores blur; it closes on a tap, a press outside or Escape. */
  const openedByTapRef = useRef(false);

  const clearTimers = useCallback(() => {
    if (openTimerRef.current != null) {
      clearTimeout(openTimerRef.current);
      openTimerRef.current = null;
    }
    if (closeTimerRef.current != null) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, []);

  const scheduleOpen = useCallback(() => {
    openedByTapRef.current = false;
    clearTimers();
    openTimerRef.current = setTimeout(
      () => setOpen(true),
      DETAILS_OPEN_DELAY_MS,
    );
  }, [clearTimers]);

  const scheduleClose = useCallback(() => {
    clearTimers();
    closeTimerRef.current = setTimeout(
      () => setOpen(false),
      DETAILS_CLOSE_DELAY_MS,
    );
  }, [clearTimers]);

  const closeNow = useCallback(() => {
    openedByTapRef.current = false;
    clearTimers();
    setOpen(false);
  }, [clearTimers]);

  const handlePointerEnter = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.pointerType !== "mouse") return;
      scheduleOpen();
    },
    [scheduleOpen],
  );

  const handlePointerLeave = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.pointerType !== "mouse") return;
      scheduleClose();
    },
    [scheduleClose],
  );

  const handleTouchPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.pointerType !== "touch" || !isTouchToggleTarget(event.target))
        return;

      touchPressRef.current = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
      };
    },
    [],
  );

  const handleTouchPointerCancel = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (touchPressRef.current?.pointerId === event.pointerId)
        touchPressRef.current = null;
    },
    [],
  );

  const handleTouchPointerUp = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const touchPress = touchPressRef.current;
      touchPressRef.current = null;

      if (
        event.pointerType !== "touch" ||
        touchPress?.pointerId !== event.pointerId ||
        !isTouchToggleTarget(event.target) ||
        Math.hypot(
          event.clientX - touchPress.startX,
          event.clientY - touchPress.startY,
        ) > TOUCH_TAP_MOVE_TOLERANCE_PX
      )
        return;

      clearTimers();
      openedByTapRef.current = !open;
      setOpen(!open);
    },
    [clearTimers, open],
  );

  /*
   * While open, Escape or a press outside closes the panel; touch has no
   * pointer to leave. Escape is captured and marked handled so an enclosing
   * dialog does not also close, but only when focus is in the card or nowhere.
   */
  useEffect(() => {
    if (!open) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || event.defaultPrevented) return;
      const active = document.activeElement;
      const shell = shellRef.current;
      if (
        active &&
        active !== document.body &&
        shell &&
        !shell.contains(active)
      )
        return;
      event.preventDefault();
      closeNow();
    };
    const onPointerDown = (event: PointerEvent) => {
      const shell = shellRef.current;
      if (
        shell &&
        event.target instanceof Node &&
        !shell.contains(event.target)
      )
        closeNow();
    };

    window.addEventListener("keydown", onKeyDown, true);
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      window.removeEventListener("keydown", onKeyDown, true);
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [closeNow, open]);

  useEffect(() => () => clearTimers(), [clearTimers]);

  return (
    <div
      aria-details={open ? detailsId : undefined}
      aria-label={focusLabel}
      className={["kpi-theme", "kpi-shell", className]
        .filter(Boolean)
        .join(" ")}
      onBlur={(event) => {
        const next = event.relatedTarget;
        // A tap moves focus to nothing; that blur must not close what it opened.
        if (openedByTapRef.current && next == null) return;
        if (next instanceof Node && event.currentTarget.contains(next)) return;
        scheduleClose();
      }}
      onFocus={(event) => {
        // Only keyboard focus opens the panel; taps and clicks focus too.
        if (!isKeyboardFocus(event.target)) return;
        scheduleOpen();
      }}
      onPointerCancel={handleTouchPointerCancel}
      onPointerDown={handleTouchPointerDown}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onPointerUp={handleTouchPointerUp}
      ref={shellRef}
      role={focusLabel ? "group" : undefined}
      tabIndex={focusLabel ? 0 : undefined}
    >
      {children}
      <div
        aria-hidden={!open}
        aria-label={detailsLabel}
        className={`kpi-details kpi-details--animate${open ? " is-open" : ""}`}
        id={detailsId}
        role="group"
      >
        <div aria-hidden="true" className="kpi-details-bridge" />
        <div className="kpi-details-panel">
          <div className="kpi-details-content">{details}</div>
        </div>
      </div>
    </div>
  );
}

/** Icon-only action button; the accessible name comes from `aria-label`. */
function KpiButton({
  className,
  type = "button",
  ...props
}: ComponentPropsWithRef<"button">) {
  return (
    <button
      className={["kpi-button", className].filter(Boolean).join(" ")}
      type={type}
      {...props}
    />
  );
}

.kpi {
  position: relative;
  display: flex;
  flex-direction: column;
  inline-size: 100%;
  block-size: 100%;
  padding: var(--kpi-padding);
  /* Sized by its own width: it may sit in a narrow column on a wide screen. */
  container: kpi / inline-size;
  overflow: hidden;
  color: var(--kpi-foreground);
  font-family: var(--kpi-font-sans);
  background: var(--kpi-surface);
  border: 1px solid var(--kpi-border);
  border-radius: var(--kpi-radius);
  backdrop-filter: blur(var(--kpi-blur));

  /* Neutral semantics get a brighter line than the muted `flat` default. */
  &.kpi--tone-positive {
    --kpi-trend-color: var(--kpi-trend-color-override, var(--kpi-success));
    --kpi-chart-color: var(--kpi-chart-color-override, var(--kpi-success));
  }

  &.kpi--tone-negative {
    --kpi-trend-color: var(--kpi-trend-color-override, var(--kpi-destructive));
    --kpi-chart-color: var(--kpi-chart-color-override, var(--kpi-destructive));
  }

  &.kpi--tone-neutral {
    --kpi-chart-color: var(
      --kpi-chart-color-override,
      var(--kpi-muted-foreground)
    );
  }
}

/* Overflow stays visible so the panel hangs below the card, out of flow. */
.kpi-shell {
  position: relative;
  display: block;
  inline-size: 100%;
  block-size: 100%;
  overflow: visible;
  interpolate-size: allow-keywords;
}

/* Focusable only when the card has no button. */
.kpi-shell:focus-visible {
  outline: 2px solid var(--kpi-ring);
  outline-offset: 2px;
  border-radius: var(--kpi-radius);
}

.kpi-details {
  position: absolute;
  inset-block-start: 100%;
  inset-inline-start: 0;
  z-index: 20;
  inline-size: 100%;
  padding-block-start: 0.5rem;
  pointer-events: none;

  &.is-open {
    pointer-events: auto;

    & .kpi-details-panel {
      block-size: auto;
      opacity: 1;
      visibility: visible;
    }

    & .kpi-details-content {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

.kpi-details-bridge {
  position: absolute;
  inset-block-start: 0;
  inset-inline: 0;
  block-size: 0.5rem;
}

/* Padding on the inner wrapper lets the panel collapse to zero. */
.kpi-details-panel {
  block-size: 0;
  overflow: hidden;
  color: var(--kpi-foreground);
  font-family: var(--kpi-font-sans);
  background: var(--kpi-surface);
  border: 1px solid var(--kpi-border);
  border-radius: var(--kpi-radius);
  opacity: 0;
  /* Keeps links in a closed panel out of the tab order. */
  visibility: hidden;
  backdrop-filter: blur(var(--kpi-blur));
  box-shadow: 0 12px 32px
    color-mix(in oklab, var(--kpi-background) 55%, transparent);
}

.kpi-details-content {
  padding: 0.875rem 1rem;
  opacity: 0;
  transform: translateY(-0.75rem);
}

.kpi-details-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
}

.kpi-details-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.75rem;
  align-items: baseline;
}

.kpi-details-label {
  margin: 0;
  color: var(--kpi-muted-foreground);
  font-size: 0.75rem;
  line-height: 1.25;
}

.kpi-details-value {
  margin: 0;
  color: var(--kpi-foreground);
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
  line-height: 1.25;
  text-align: end;
}

/* --- Header --------------------------------------------------------------- */

.kpi-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: flex-start;
  gap: 0.5rem;
  margin-block-end: 0.5rem;
}

.kpi-title {
  /* Restated here so a page's own `h3` rule cannot win. */
  margin: 0;
  padding: 0;
  letter-spacing: normal;
  text-transform: none;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  color: var(--kpi-muted-foreground);
  font-weight: 500;
  font-size: 0.875rem;
  font-family: var(--kpi-font-sans);
  line-height: 1.25rem;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Always visible on touch; revealed on hover or focus elsewhere. */
.kpi-actions {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;

  @media (hover: hover) {
    opacity: 0;
    transition: opacity var(--kpi-duration) ease;

    .kpi:hover &,
    .kpi:focus-within & {
      opacity: 1;
    }
  }
}

/* --- Action button ------------------------------------------------------- */

.kpi-button {
  /* Restated so a page's own `button` rule cannot win. */
  margin: 0;
  padding: 0;
  min-inline-size: 0;
  min-block-size: 0;
  font: inherit;
  box-shadow: none;
  cursor: pointer;
  appearance: none;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  color: var(--kpi-muted-foreground);
  background: transparent;
  background-clip: padding-box;
  border: 1px solid transparent;
  border-radius: var(--kpi-radius-md);
  outline: none;
  transition:
    color var(--kpi-duration) ease,
    background-color var(--kpi-duration) ease,
    border-color var(--kpi-duration) ease,
    transform var(--kpi-duration) ease;
  user-select: none;

  & > svg {
    flex-shrink: 0;
    inline-size: 0.75rem;
    block-size: 0.75rem;
    pointer-events: none;
  }

  &:hover {
    color: var(--kpi-foreground);
    background: color-mix(in oklab, var(--kpi-muted) 50%, transparent);
  }

  &:focus-visible {
    outline: 2px solid var(--kpi-ring);
    outline-offset: 2px;
  }

  &:active {
    transform: translateY(1px);
  }

  &.kpi-button--success {
    color: var(--kpi-success);
  }
}

/* --- Value + chart ------------------------------------------------------- */

.kpi-body {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-block-start: 0.25rem;
}

.kpi-value {
  position: relative;
  z-index: 1;
  display: block;
  min-inline-size: 0;
  color: var(--kpi-foreground);
  font-weight: 700;
  font-size: 1.875rem;
  font-family: var(--kpi-font-mono);
  line-height: 1;
  letter-spacing: -0.025em;

  @container kpi (inline-size >= 20rem) {
    font-size: 2.25rem;
  }

  & .kpi-value-part--notation,
  & .kpi-value-part--unit {
    color: var(--kpi-foreground);
  }
}

.kpi-value-part--digits {
  font-variant-numeric: tabular-nums;
}

.kpi-trend {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-inline-size: 0;
  font-size: 0.875rem;
}

.kpi-trend-badge {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.125rem 0.375rem;
  color: var(--kpi-trend-color);
  font-weight: 500;
  font-family: var(--kpi-font-mono);
  font-variant-numeric: tabular-nums;
  background: var(--kpi-surface-muted);
  border: 1px solid var(--kpi-border-subtle);
  border-radius: var(--kpi-radius-sm);
}

.kpi-trend-comparison {
  color: var(--kpi-muted-foreground);
  font-size: 0.75rem;
}

.kpi-chart {
  position: absolute;
  inset-inline-end: 0;
  inset-block-end: 8px;
  z-index: 0;
  display: none;
  color: var(--kpi-chart-color);
  opacity: 0.8;
  transition: opacity var(--kpi-duration-slow) ease;
  pointer-events: none;

  .kpi:hover & {
    opacity: 1;
  }

  @container kpi (inline-size >= 20rem) {
    display: block;
  }
}

/* --- Target footer ------------------------------------------------------- */

.kpi-footer {
  margin-block-start: 1.5rem;
  padding-block-start: 1rem;
  border-block-start: 1px solid var(--kpi-border-subtle);
}

/* When label and figures do not fit, the figures wrap whole: split, they read as two numbers. */
.kpi-footer-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.125rem 1rem;
  margin-block-end: 0.375rem;
  font-size: 0.75rem;
}

.kpi-footer-label {
  flex: 1 1 auto;
  min-inline-size: 0;
  color: var(--kpi-muted-foreground);
}

.kpi-footer-value {
  margin-inline-start: auto;
  color: var(--kpi-muted-foreground);
  font-family: var(--kpi-font-mono);
  white-space: nowrap;
}

.kpi-progress {
  inline-size: 100%;
  block-size: 0.375rem;
  overflow: hidden;
  background: var(--kpi-muted);
  border-radius: 9999px;
}

.kpi-progress-fill {
  /* `--kpi-progress` is a unitless fraction written by the component; the bar
     is sized from it rather than from an inline width so the stylesheet owns
     both the resting size and how it gets there. `inline-size` and not a
     `scaleX` transform: the bar is six pixels tall, so there is no layout cost
     worth trading a logical property for, and this stays right in both writing
     directions. */
  inline-size: calc(var(--kpi-progress, 0) * 100%);
  block-size: 100%;
  background: var(--kpi-foreground);
  opacity: 0.55;
}

/* --- Loading skeleton --------------------------------------------------- */

.kpi--loading {
  gap: 1rem;
  min-block-size: 10rem;
}

.kpi-skeleton {
  background: var(--kpi-muted);
  border-radius: var(--kpi-radius-sm);

  &.kpi-skeleton--title {
    inline-size: 33%;
    block-size: 1rem;
  }

  &.kpi-skeleton--value {
    inline-size: 50%;
    block-size: 2.5rem;
  }

  &.kpi-skeleton--footer {
    inline-size: 25%;
    block-size: 0.75rem;
    margin-block-start: auto;
  }
}

/* --- Right-to-left ------------------------------------------------------ */

/* Logical properties follow `dir`; drawings are mirrored so time runs from the
 * inline start. Not `:dir()`: Vite and Next.js lower it to `:lang()`, which
 * ignores `dir`. */
:where([dir="rtl"]) {
  --kpi-mirror: -1;
}

:where([dir="ltr"]) {
  --kpi-mirror: 1;
}

.kpi-trend-badge svg,
.kpi-chart svg {
  transform: scaleX(var(--kpi-mirror, 1));
}

/* All motion is CSS; reduced motion is handled once, at the end of this file. */

.kpi-details--animate {
  & .kpi-details-panel {
    transition:
      block-size var(--kpi-details-duration-out) ease-in,
      opacity var(--kpi-details-duration-out) ease-in,
      visibility 0s linear var(--kpi-details-duration-out);
  }

  & .kpi-details-content {
    transition:
      opacity calc(var(--kpi-details-duration-out) / 2) ease-in,
      transform var(--kpi-details-duration-out) ease-in;
  }

  &.is-open .kpi-details-panel {
    transition:
      block-size var(--kpi-details-duration-in) var(--kpi-details-ease),
      opacity 120ms ease-out,
      visibility 0s;
  }

  &.is-open .kpi-details-content {
    transition:
      opacity 200ms ease-out 60ms,
      transform var(--kpi-details-duration-in) var(--kpi-details-ease);
  }
}

/* --- Chart entrances ----------------------------------------------------- */

/* A transition cannot run on mount; a `from`-only keyframe fills the bar to its own width. */
.kpi-progress-fill {
  transition: inline-size var(--kpi-duration-progress) ease-out;
  animation: kpi-progress-fill var(--kpi-duration-progress) ease-out;
}

@keyframes kpi-progress-fill {
  from {
    inline-size: 0;
  }
}

/*
 * Bars rise from the baseline in turn. 36 is `HEIGHT - CHART_VERTICAL_PADDING`.
 * `backwards` holds each bar at zero through its delay.
 */
.kpi-chart rect {
  transition:
    height var(--kpi-duration-bar) ease-out,
    y var(--kpi-duration-bar) ease-out;
  animation: kpi-bar-rise var(--kpi-duration-bar) cubic-bezier(0.22, 1, 0.36, 1)
    backwards;
  animation-delay: calc(var(--kpi-bar-index, 0) * var(--kpi-bar-stagger));
}

@keyframes kpi-bar-rise {
  from {
    height: 0;
    y: 36px;
  }
}

/* Line draw: with `pathLength="1"`, a dash of 1 is the whole line. */
.kpi-chart polyline {
  stroke-dasharray: 1;
  animation: kpi-line-draw var(--kpi-duration-line) ease-in-out backwards;
}

@keyframes kpi-line-draw {
  from {
    stroke-dashoffset: 1;
    opacity: 0;
  }
  to {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}

/* --- Everything else ----------------------------------------------------- */

@keyframes kpi-fade-in {
  from {
    opacity: 0.5;
    transform: translateY(-2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.kpi-value-animate {
  animation: kpi-fade-in var(--kpi-duration-slow) ease-out forwards;
}

.kpi--loading {
  animation: kpi-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes kpi-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .kpi,
  .kpi *,
  .kpi-shell,
  .kpi-shell * {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    /* Delays too: a staggered bar would otherwise wait invisible, then appear. */
    transition-delay: 0ms !important;
    animation-delay: 0ms !important;
  }
}

/* Zero-specificity defaults the card needs whatever the page's reset. What a
 * page's element rules would override is restated on the classes in layout.css. */

:where(.kpi, .kpi-shell) {
  &,
  & :where(*, *::before, *::after) {
    box-sizing: border-box;
  }

  & :where(dl, dt, dd) {
    margin: 0;
  }
}

:where(.kpi) {
  & :where(h3, p, span, div, svg) {
    margin: 0;
    padding: 0;
  }

  & :where(button) {
    margin: 0;
    padding: 0;
    color: inherit;
    font: inherit;
    letter-spacing: inherit;
    background: none;
    border: 0;
    cursor: pointer;
    appearance: none;
  }

  & :where(svg) {
    display: block;
    overflow: visible;
  }
}

/* Visually hidden; absolute so it adds no flex gap. */
.kpi-sr-only {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  white-space: nowrap;
  border: 0;
  clip-path: inset(50%);
}

/*
 * Tokens live on the card, not `:root`. Dark mode follows the nearest
 * `data-theme` or `.dark`, else the operating system.
 *
 * Not `light-dark()`: Vite and Next.js polyfill it in a way that needs a
 * literal `color-scheme`. Instead one of `--kpi-light` / `--kpi-dark` is
 * `initial` (so `var()` takes its fallback) and the other is empty.
 */

:where([data-theme="light"]) {
  --kpi-color-scheme: light;
  --kpi-light: initial;
  --kpi-dark: ;
}

:where([data-theme="dark"], .dark) {
  --kpi-color-scheme: dark;
  --kpi-light: ;
  --kpi-dark: initial;
}

/* Any other `data-theme` value falls back to the operating system. */
.kpi-theme:not(
  :is([data-theme="light"], [data-theme="dark"], .dark),
  :is([data-theme="light"], [data-theme="dark"], .dark) *
) {
  --kpi-light: initial;
  --kpi-dark: ;

  @media (prefers-color-scheme: dark) {
    --kpi-light: ;
    --kpi-dark: initial;
  }
}

/* --- Light: Tailwind slate --------------------------------------------- */
.kpi-theme {
  --kpi-radius: var(--kpi-radius-override, 0.75rem);

  --kpi-radius-sm: var(--kpi-radius-sm-override, 0.25rem);
  --kpi-radius-md: var(--kpi-radius-md-override, 0.375rem);

  --kpi-background: var(
    --kpi-background-override,
    var(--kpi-light, oklch(98.4% 0.003 247.858))
      var(--kpi-dark, oklch(14.1% 0.005 285.823))
  ); /* slate-50 / zinc-950 */
  --kpi-foreground: var(
    --kpi-foreground-override,
    var(--kpi-light, oklch(12.9% 0.042 264.695))
      var(--kpi-dark, oklch(98.5% 0 0))
  ); /* slate-950 / zinc-50 */
  --kpi-card: var(
    --kpi-card-override,
    var(--kpi-light, oklch(100% 0 0)) var(--kpi-dark, oklch(21% 0.006 285.885))
  ); /* white / zinc-900 */
  --kpi-card-foreground: var(
    --kpi-card-foreground-override,
    var(--kpi-foreground)
  );
  --kpi-muted: var(
    --kpi-muted-override,
    var(--kpi-light, oklch(96.8% 0.007 247.896))
      var(--kpi-dark, oklch(27.4% 0.006 286.033))
  ); /* slate-100 / zinc-800 */
  --kpi-muted-foreground: var(
    --kpi-muted-foreground-override,
    var(--kpi-light, oklch(44.6% 0.043 257.281))
      var(--kpi-dark, oklch(70.5% 0.015 286.067))
  ); /* slate-600 / zinc-400 */
  --kpi-destructive: var(
    --kpi-destructive-override,
    var(--kpi-light, oklch(58.6% 0.253 17.585))
      var(--kpi-dark, oklch(71.2% 0.194 13.428))
  ); /* rose-600 / rose-400 */
  --kpi-success: var(
    --kpi-success-override,
    var(--kpi-light, oklch(59.6% 0.145 163.225))
      var(--kpi-dark, oklch(76.5% 0.177 163.223))
  ); /* emerald-600 / emerald-400 */
  --kpi-border: var(
    --kpi-border-override,
    var(--kpi-light, oklch(92.9% 0.013 255.508))
      var(--kpi-dark, oklch(100% 0 0 / 10%))
  ); /* slate-200 / white 10% */
  --kpi-ring: var(
    --kpi-ring-override,
    var(--kpi-light, oklch(70.4% 0.04 256.788))
      var(--kpi-dark, oklch(55.2% 0.016 285.938))
  ); /* slate-400 / zinc-500 */
  color-scheme: var(--kpi-color-scheme, light dark);
}

/* Card-specific tokens, built on the theme above. */
.kpi,
.kpi-shell {
  --kpi-surface: var(
    --kpi-surface-override,
    var(--kpi-light, color-mix(in oklab, var(--kpi-card) 80%, transparent))
      var(--kpi-dark, color-mix(in oklab, var(--kpi-card) 70%, transparent))
  );
  --kpi-surface-muted: var(
    --kpi-surface-muted-override,
    var(--kpi-light, color-mix(in oklab, var(--kpi-card) 55%, transparent))
      var(--kpi-dark, color-mix(in oklab, var(--kpi-card) 50%, transparent))
  );
  --kpi-border-subtle: var(
    --kpi-border-subtle-override,
    var(--kpi-light, color-mix(in oklab, var(--kpi-foreground) 6%, transparent))
      var(
        --kpi-dark,
        color-mix(in oklab, var(--kpi-foreground) 5%, transparent)
      )
  );
  --kpi-blur: var(--kpi-blur-override, 12px);
  --kpi-padding: var(--kpi-padding-override, 1.5rem);
  --kpi-trend-color: var(
    --kpi-trend-color-override,
    var(--kpi-muted-foreground)
  );
  --kpi-chart-color: var(
    --kpi-chart-color-override,
    var(--kpi-muted-foreground)
  );

  --kpi-font-sans: var(
    --kpi-font-sans-override,
    "Inter",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    "Helvetica Neue",
    Arial,
    sans-serif
  );
  --kpi-font-mono: var(
    --kpi-font-mono-override,
    "JetBrains Mono",
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    "Liberation Mono",
    monospace
  );

  --kpi-duration: var(--kpi-duration-override, 200ms);
  --kpi-duration-slow: var(--kpi-duration-slow-override, 300ms);
  /* The three chart animations. */
  --kpi-duration-progress: var(--kpi-duration-progress-override, 1s);
  --kpi-duration-bar: var(--kpi-duration-bar-override, 420ms);
  --kpi-duration-line: var(--kpi-duration-line-override, 1200ms);
  /* Stagger between neighbouring sparkline bars. */
  --kpi-bar-stagger: var(--kpi-bar-stagger-override, 20ms);
  --kpi-details-duration-in: var(--kpi-details-duration-in-override, 320ms);
  --kpi-details-duration-out: var(--kpi-details-duration-out-override, 180ms);
  --kpi-details-ease: var(
    --kpi-details-ease-override,
    cubic-bezier(0.22, 1, 0.36, 1)
  );
}
